async def act(page):
    import asyncio
    import csv
    import io
    import os

    # Navigate to Orders management page (relative goto as requested)
    await page.goto('/index.php/admin/sales/order/')
    # Give the grid and toolbar a moment to render
    await asyncio.sleep(1)

    # Find the toolbar cell that mentions 'Export to' (preferred scoping like KB helper)
    export_cell = None
    cells = page.get_by_role('cell')
    cell_count = await cells.count()
    for i in range(cell_count):
        c = cells.nth(i)
        try:
            txt = (await c.inner_text() or '').strip()
        except Exception:
            txt = ''
        if 'export to' in txt.lower():
            export_cell = c
            break

    # Fallback: if no scoped cell found, search page-level comboboxes/buttons later
    selected_combobox = None
    if export_cell is not None:
        # Try to find a combobox inside this cell
        cbs = export_cell.get_by_role('combobox')
        if await cbs.count() > 0:
            # Attempt to robustly choose CSV option
            cb = cbs.first
            try:
                await cb.select_option(label='CSV')
                selected_combobox = cb
            except Exception:
                # read option labels and choose one containing 'CSV'
                try:
                    opts = cb.get_by_role('option')
                    opt_texts = await opts.all_inner_texts()
                except Exception:
                    opt_texts = []
                csv_label = None
                for t in opt_texts:
                    if t and 'csv' in t.lower():
                        csv_label = t
                        break
                if csv_label:
                    try:
                        await cb.select_option(label=csv_label)
                        selected_combobox = cb
                    except Exception:
                        selected_combobox = None

    # If no export_cell or combobox selection unsuccessful, fallback to scanning all comboboxes on page
    if selected_combobox is None:
        all_cbs = page.get_by_role('combobox')
        cb_count = await all_cbs.count()
        for i in range(cb_count):
            cb = all_cbs.nth(i)
            try:
                await cb.select_option(label='CSV')
                selected_combobox = cb
                break
            except Exception:
                try:
                    opts = cb.get_by_role('option')
                    opt_texts = await opts.all_inner_texts()
                except Exception:
                    opt_texts = []
                csv_label = None
                for t in opt_texts:
                    if t and 'csv' in t.lower():
                        csv_label = t
                        break
                if csv_label:
                    try:
                        await cb.select_option(label=csv_label)
                        selected_combobox = cb
                        break
                    except Exception:
                        continue

    # Find the Export button. Prefer the one scoped to export_cell when available
    export_button = None
    if export_cell is not None:
        # try direct named button first
        try:
            btns = export_cell.get_by_role('button')
            btn_count = await btns.count()
            for i in range(btn_count):
                b = btns.nth(i)
                try:
                    bname = (await b.inner_text() or '').strip()
                except Exception:
                    bname = ''
                if 'export' in bname.lower() or bname.lower() == 'export':
                    export_button = b
                    break
        except Exception:
            export_button = None

    # Fallback: scan page-level buttons
    if export_button is None:
        all_buttons = page.get_by_role('button')
        btn_count = await all_buttons.count()
        for i in range(btn_count):
            b = all_buttons.nth(i)
            try:
                txt = (await b.inner_text() or '').strip()
            except Exception:
                txt = ''
            if 'export' in txt.lower():
                export_button = b
                break

    if export_button is None:
        raise RuntimeError('Could not find an Export button on the Orders page')

    download_path = 'orders_export.csv'
    try:
        if os.path.exists(download_path):
            os.remove(download_path)
    except Exception:
        pass

    try:
        async with page.expect_download() as dd:
            # Use the full .get_by_role() path for clicking the button when possible
            await export_button.click()
        download = await dd.value
        await download.save_as(download_path)
    except Exception as e:
        raise RuntimeError(f'Export download failed: {e}')

    # Read and decode CSV (utf-8 primary, latin-1 fallback)
    with open(download_path, 'rb') as f:
        raw = f.read()
    try:
        orders_csv = raw.decode('utf-8')
    except Exception:
        orders_csv = raw.decode('latin-1')

    # Parse orders CSV to count canceled orders per customer (prefer email then name)
    reader = csv.DictReader(io.StringIO(orders_csv))
    headers = reader.fieldnames or []
    status_col = None
    email_col = None
    name_col = None
    for h in headers:
        if not h:
            continue
        lh = h.strip().lower()
        if status_col is None and ('status' in lh or 'order status' in lh or lh == 'state'):
            status_col = h
        if email_col is None and 'email' in lh:
            email_col = h
        if name_col is None and ('name' in lh or 'billing name' in lh or 'customer' in lh):
            name_col = h

    key_col = email_col or name_col or (headers[0] if headers else None)

    cancellations = {}
    # iterate rows defensively
    for row in reader:
        if not row:
            continue
        status = ''
        key = ''
        if status_col and status_col in row:
            status = (row.get(status_col) or '').strip().lower()
        else:
            for h in headers:
                if h and ('status' in h.lower() or 'state' in h.lower()):
                    status = (row.get(h) or '').strip().lower()
                    break
        if key_col and key_col in row:
            key = (row.get(key_col) or '').strip()
        if status and 'cancel' in status:
            cancellations[key] = cancellations.get(key, 0) + 1

    if not cancellations:
        raise RuntimeError('No canceled orders found in exported orders CSV')

    # determine top customer key
    top_key = max(cancellations.items(), key=lambda kv: kv[1])[0]
    top_email = None
    top_name = None
    if '@' in (top_key or ''):
        top_email = top_key
    else:
        top_name = top_key

    # Use KB helper to export customers CSV and retrieve contact details
    result = await export_customers_csv_via_grid(page, filename='customers_export.csv')
    customers_csv = None
    if isinstance(result, dict):
        customers_csv = result.get('csv')
    elif isinstance(result, str):
        customers_csv = result
    else:
        # attempt to read file saved by helper
        try:
            with open('customers_export.csv', 'rb') as f:
                rawc = f.read()
            try:
                customers_csv = rawc.decode('utf-8')
            except Exception:
                customers_csv = rawc.decode('latin-1')
        except Exception:
            raise RuntimeError('Could not retrieve customers CSV from helper result')

    if not customers_csv:
        raise RuntimeError('Customers CSV is empty')

    c_reader = csv.DictReader(io.StringIO(customers_csv))
    cust_rows = list(c_reader)
    found_email = ''
    found_name = ''
    found_phone = ''

    def extract_fields(row):
        e = ''
        n = ''
        p = ''
        for h, v in row.items():
            if not h:
                continue
            lh = h.strip().lower()
            val = (v or '').strip()
            if not e and 'email' in lh:
                e = val
            if not n and ('name' == lh or 'customer' in lh or 'full name' in lh or 'firstname' in lh or 'lastname' in lh):
                n = val
            if not p and ('telephone' in lh or 'phone' in lh or 'tel' in lh):
                p = val
        return e, n, p

    # Try to match by email first
    if top_email:
        for row in cust_rows:
            e, n, p = extract_fields(row)
            if e and top_email and e.lower() == top_email.lower():
                found_email, found_name, found_phone = e, n, p
                break
        if not found_email:
            local = top_email.split('@')[0]
            for row in cust_rows:
                e, n, p = extract_fields(row)
                if e and local.lower() in e.lower():
                    found_email, found_name, found_phone = e, n, p
                    break

    # Match by name if needed
    if not found_email and top_name:
        for row in cust_rows:
            e, n, p = extract_fields(row)
            if n and top_name and top_name.lower() in n.lower():
                found_email, found_name, found_phone = e, n, p
                break

    if not (found_email or found_name):
        for row in cust_rows:
            e, n, p = extract_fields(row)
            if top_key and ((e and top_key.lower() in e.lower()) or (n and top_key.lower() in n.lower())):
                found_email, found_name, found_phone = e, n, p
                break

    if not (found_email or found_name):
        raise RuntimeError('Could not locate customer details for top cancellations key')

    final_email = (found_email or '').strip()
    final_name = (found_name or '').strip()
    final_phone = (found_phone or '').strip()

    # Return the triple as requested (email, name, phone)
    return (final_email, final_name, final_phone)

